def shapes() -> list[str]:
    return sorted(FIXTURES)


def rows() -> list[tuple[str, str, str, str]]:
    """`(shape, path, expected_class, content)` for every fixture row, in stable order."""
    out: list[tuple[str, str, str, str]] = []
    for shape in shapes():
        for path, cls, content in FIXTURES[shape]["files"]:
            out.append((shape, path, cls, content))
    return out


def paths() -> list[str]:
    return [row[1] for row in rows()]


def counts() -> dict[str, int]:
    """Rows per expected class — the fixture set's own coverage report."""
    out: dict[str, int] = {}
    for _shape, _path, cls, _content in rows():
        out[cls] = out.get(cls, 0) + 1
    return {cls: out.get(cls, 0) for cls in C.PATH_CLASSES}
